-- IELTS example review: 17 fixes (see docs/ielts-review/examples-fixes-0275.md).
UPDATE ielts_examples SET sentence_en = 'Polar regions receive very little sunlight during the winter months.', sentence_zh = '极地地区在冬季几个月里日照极少。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'polar-1' AND sentence_en = 'Polar bears depend on sea ice for hunting seals.' AND sentence_zh = '北极熊依靠海冰来捕猎海豹。' AND target = 'Polar';

UPDATE ielts_examples SET sentence_zh = '该国大部分葡萄酒都产自这一地区。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'region-1' AND sentence_en = 'This region of the country produces most of its wine.' AND sentence_zh = '该国这一地区出产该国大部分葡萄酒。' AND target = 'region';

UPDATE ielts_examples SET sentence_en = 'Some desert insects collect dew on their backs and then drink it.', sentence_zh = '一些沙漠昆虫用背部收集露水,然后喝掉。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'dew-1' AND sentence_en = 'Some desert insects collect dew from their bodies to drink.' AND sentence_zh = '一些沙漠昆虫收集身上的露水来饮用。' AND target = 'dew';

UPDATE ielts_examples SET sentence_zh = '螃蟹和龙虾都属于甲壳动物。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'crustacean-1' AND sentence_en = 'Crabs and lobsters belong to a group of animals called crustaceans.' AND sentence_zh = '螃蟹和龙虾属于一类被称为甲壳动物的动物。' AND target = 'crustaceans';

UPDATE ielts_examples SET sentence_en = 'Rising sea temperatures have caused large areas of coral to turn white and die.', sentence_zh = '海水温度上升导致大片珊瑚变白死亡。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'coral-1' AND sentence_en = 'Rising temperatures have caused large areas of coral to turn white and die.' AND sentence_zh = '气温上升导致大片珊瑚变白死亡。' AND target = 'coral';

UPDATE ielts_examples SET sentence_en = 'The British established their first permanent colony in North America in 1607.', sentence_zh = '1607 年,英国人在北美建立了第一个永久殖民地。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'colony-2' AND sentence_en = 'The British established their first colony in North America in the 1600s.' AND sentence_zh = '英国人在 17 世纪在北美建立了第一个殖民地。' AND target = 'colony';

UPDATE ielts_examples SET sentence_en = 'Some vultures have a strong sense of smell that helps them to find carrion.', sentence_zh = '有些秃鹫嗅觉灵敏,能借此找到腐肉。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'carrion-1' AND sentence_en = 'Vultures have a strong sense of smell that helps them to find carrion.' AND sentence_zh = '秃鹫嗅觉灵敏,这有助于它们找到腐肉。' AND target = 'carrion';

UPDATE ielts_examples SET sentence_en = 'Salmon swim back up the river where they were born in order to spawn.', sentence_zh = '鲑鱼会逆流游回出生的河流产卵。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'spawn-1' AND sentence_en = 'Salmon swim back up the same river to spawn each year.' AND sentence_zh = '鲑鱼每年逆流游回同一条河产卵。' AND target = 'spawn';

UPDATE ielts_examples SET sentence_zh = '这种病毒的一种新毒株已在该地区迅速传播。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'strain-1' AND sentence_en = 'A new strain of the virus has spread rapidly through the region.' AND sentence_zh = '这种病毒的一个新品种已在该地区迅速传播。' AND target = 'strain';

UPDATE ielts_examples SET sentence_en = 'Many types of orchid depend on a particular insect for pollination.', sentence_zh = '许多兰花都依赖某种特定的昆虫授粉。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'orchid-1' AND sentence_en = 'Each type of orchid depends on a particular insect for pollination.' AND sentence_zh = '每一种兰花都依赖特定的昆虫授粉。' AND target = 'orchid';

UPDATE ielts_examples SET sentence_en = 'An ion is an atom that has gained or lost one or more electrons.', sentence_zh = '离子是得到或失去一个或多个电子的原子。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'ion-1' AND sentence_en = 'An ion is an atom that has gained or lost an electron.' AND sentence_zh = '离子是得到或失去电子的原子。' AND target = 'ion';

UPDATE ielts_examples SET sentence_en = 'Platinum is a rare metal used in jewellery and in car exhaust systems.', sentence_zh = '铂是一种稀有金属,用于珠宝和汽车排气系统。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'platinum-1' AND sentence_en = 'Platinum is a rare metal used in car engines and jewellery.' AND sentence_zh = '铂是一种稀有金属,用于汽车发动机和珠宝。' AND target = 'Platinum';

UPDATE ielts_examples SET sentence_en = 'Dolphins find their prey using ultrasonic clicks that humans cannot hear.', sentence_zh = '海豚用人类听不到的超声波咔嗒声寻找猎物。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'ultrasonic-1' AND sentence_en = 'Dolphins communicate using ultrasonic sounds that humans cannot hear.' AND sentence_zh = '海豚用人类听不到的超声波交流。' AND target = 'ultrasonic';

UPDATE ielts_examples SET sentence_zh = '引力使行星沿轨道绕太阳运行。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'gravity-1' AND sentence_en = 'Gravity keeps the planets moving in their paths around the Sun.' AND sentence_zh = '重力使行星沿轨道绕太阳运行。' AND target = 'Gravity';

UPDATE ielts_examples SET sentence_en = 'Lunar rocks brought back to Earth have helped scientists understand the Moon''s history.', sentence_zh = '带回地球的月球岩石帮助科学家了解月球的历史。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'lunar-1' AND sentence_en = 'Lunar rocks brought back to Earth have helped scientists understand its history.' AND sentence_zh = '带回地球的月球岩石帮助科学家了解它的历史。' AND target = 'Lunar';

UPDATE ielts_examples SET sentence_en = 'A high correlation coefficient shows that the two variables are closely related.', sentence_zh = '相关系数高表明这两个变量密切相关。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'coefficient-1' AND sentence_en = 'A high coefficient shows that the two variables are closely related.' AND sentence_zh = '系数高表明这两个变量密切相关。' AND target = 'coefficient';

UPDATE ielts_examples SET sentence_en = 'The factorial of five is the product of all whole numbers from one to five.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'factorial-1' AND sentence_en = 'The factorial of five is the product of all whole numbers up to five.' AND sentence_zh = '五的阶乘是从一到五所有整数的乘积。' AND target = 'factorial';
